#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6
REPO_ROOT=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." && pwd -P)
cd -- "$REPO_ROOT"
ENV_FILE="$REPO_ROOT/.env"
grep -qxF '.env' .gitignore || { warn '.gitignore must exclude .env.'; exit 1; }
git check-ignore -q .env || { warn '.env is not ignored; refusing.'; exit 1; }
for tool in gh git cygpath clip.exe python powershell.exe; do
  command -v "$tool" >/dev/null || { warn "Missing required tool: $tool"; exit 1; }
done
export PYTHONUTF8=1 TZ=UTC
export PYTHONPYCACHEPREFIX="${LOCALAPPDATA:?LOCALAPPDATA is required}/sinceai-pycache"

banner "Sunday: publish and submit before 10:00 EET"

stage "Public-repository safety and old backup cleanup"
git fetch --all
# No content is read. An error collecting either path list is a hard failure.
history_paths=$(git -c core.quotepath=false log --all --name-only --format=) || exit 1
tracked_paths=$(git -c core.quotepath=false ls-files) || exit 1
unsafe=0
for source in history tracked; do
  if [[ "$source" == history ]]; then paths=$history_paths; else paths=$tracked_paths; fi
  for pattern in '^Briefs/' 'rowmap_' '(^|/)truth/' '^\.env$'; do
    count=$(printf '%s\n' "$paths" | awk -v pattern="$pattern" 'tolower($0) ~ tolower(pattern) { n++ } END { print n+0 }')
    printf '  %s: %s matched paths for %s\n' "$source" "$count" "$pattern"
    if (( count > 0 )); then
      unsafe=1
      printf '%s\n' "$paths" | awk -v pattern="$pattern" 'tolower($0) ~ tolower(pattern)' | sort -u
    fi
  done
done
(( unsafe == 0 )) || { warn 'Unsafe repository history/index. Stop and arrange cleanup before publishing.'; exit 1; }
temp_windows=${TEMP:-${TMP:-${LOCALAPPDATA:?}/Temp}}
temp_dir=$(cd -- "$(cygpath -u "$temp_windows")" && pwd -P) || exit 1
shopt -s nullglob
backups=("$temp_dir"/sinceai-backup-*.git)
if (( ${#backups[@]} == 0 )); then say 'No sinceai-backup-*.git backups found in Windows TEMP.'; fi
for backup in "${backups[@]}"; do
  [[ -d "$backup" && ! -L "$backup" ]] || { warn 'Unexpected backup type; inspect it manually.'; exit 1; }
  say "Backup (contains kit and truth/): $(cygpath -w "$backup")"
  if confirm "Permanently delete this specific backup: $(cygpath -w "$backup")?"; then
    rm -rf -- "$backup"
    [[ ! -e "$backup" ]] || { warn 'Backup deletion did not complete.'; exit 1; }
  else
    warn 'Backup retained locally; never upload it.'
  fi
done

stage "Make Kivaste/sinceai public"
if confirm 'Make Kivaste/sinceai PUBLIC (including its history)?'; then
  gh repo edit Kivaste/sinceai --visibility public --accept-visibility-change-consequences
else
  warn 'Publication declined; stopping before the submission form.'
  exit 1
fi
gh repo view Kivaste/sinceai --json visibility
visibility=$(gh repo view Kivaste/sinceai --json visibility --jq .visibility) || exit 1
[[ "$visibility" == PUBLIC ]] || { warn 'Repository is not verified PUBLIC.'; exit 1; }

stage "Upload the demo video"
open_url 'https://studio.youtube.com'
step 'Upload the demo: less than 2 minutes, product working in the first 20 seconds, English narration.'
step 'Set visibility to Unlisted or Public, then copy the share URL.'
ask VIDEO_URL 'Video URL:'
[[ "$VIDEO_URL" == https://* ]] || { warn 'An HTTPS video URL is required.'; exit 1; }
write_env VIDEO_URL "$VIDEO_URL"

stage "Create the source ZIP from origin/main"
desktop="$(cygpath -u "${USERPROFILE:?USERPROFILE is required}")/Desktop"
mkdir -p -- "$desktop"
SOURCE_ZIP="$desktop/sinceai-source.zip"
if [[ -e "$SOURCE_ZIP" ]] && ! confirm 'Replace the existing Desktop/sinceai-source.zip?'; then exit 1; fi
git archive --format=zip -o "$SOURCE_ZIP" origin/main
zip_size=$(wc -c < "$SOURCE_ZIP")
(( zip_size < 100000000 )) || { warn 'Source ZIP is 100 MB or larger; submission aborted.'; exit 1; }
SOURCE_ZIP=$(cygpath -w "$SOURCE_ZIP")
say "Source ZIP: $SOURCE_ZIP ($zip_size bytes)"
write_env SOURCE_ZIP "$SOURCE_ZIP"

stage "Fill the sinceai.app submission"
open_url 'https://sinceai.app'
step "Open your team's submission. Each field below goes on the Windows clipboard in order."
story_keys=(PROJECT_NAME PROJECT_TAGLINE DESCRIPTION BUILT_WITH)
story_files=(name.txt tagline.txt description.md built-with.txt)
REPOSITORY_URL='https://github.com/Kivaste/sinceai'
video_changed=0
while true; do
  # Never read drafts: the finalisation ticket supplies header-free, resolved copy.
  for index in "${!story_keys[@]}"; do
    field=${story_keys[$index]}
    story_file="$REPO_ROOT/docs/story/final/${story_files[$index]}"
    if [[ -f "$story_file" ]]; then
      if value=$(python -c 'import sys; from pathlib import Path; print(Path(sys.argv[1]).read_text(encoding="utf-8-sig").strip(), end="")' "$story_file" 2>/dev/null); then
        printf -v "$field" '%s' "$value"
      else
        warn "Cannot read finalised ${story_files[$index]}; fix the file before retrying."
        printf -v "$field" '%s' ''
      fi
    else
      warn "Missing docs/story/final/${story_files[$index]}; run the story-finalisation ticket first."
      ask "$field" "Or enter finalised $field manually (not draft copy):"
    fi
  done

  # Validate ALL fields before the first clipboard write; never paste partial copy.
  invalid=0
  video_invalid=0
  for field in "${story_keys[@]}" REPOSITORY_URL VIDEO_URL; do
    value=${!field}
    field_invalid=0
    if [[ -z "$value" ]]; then
      warn "$field is empty; finalised text is required."
      field_invalid=1
    fi
    if [[ "$value" == *'<!--'* || "$value" == *'-->'* || "$value" == *'{{'* || "$value" == *'}}'* ]]; then
      warn "$field contains an HTML comment marker or unresolved placeholder; finalise it before copying."
      field_invalid=1
    fi
    case "$field" in
      PROJECT_NAME) limit=80 ;;
      PROJECT_TAGLINE) limit=140 ;;
      DESCRIPTION) limit=5000 ;;
      *) limit=0 ;;
    esac
    if (( limit > 0 )); then
      length=$(printf '%s' "$value" | python -c 'import sys; print(len(sys.stdin.read()))')
      say "$field: $length characters (maximum $limit)."
      if (( length > limit )); then
        warn "$field exceeds its $limit-character limit; copying is blocked."
        field_invalid=1
      fi
    fi
    if [[ "$field" == VIDEO_URL && "$value" != https://* ]]; then
      warn 'VIDEO_URL must be an HTTPS URL.'
      field_invalid=1
    fi
    if (( field_invalid )); then
      invalid=1
      if [[ "$field" == VIDEO_URL ]]; then video_invalid=1; fi
    fi
  done
  if (( invalid == 0 )); then break; fi
  warn 'No fields were copied. Fix the finalised files or manual entries, then re-run stage 5.'
  if ! confirm 'Re-run stage 5 input and validation now?'; then exit 1; fi
  if (( video_invalid )); then
    ask VIDEO_URL 'Correct the video URL (HTTPS, no comment markers or placeholders):'
    video_changed=1
  fi
done
write_env BUILT_WITH "$BUILT_WITH"
if (( video_changed )); then write_env VIDEO_URL "$VIDEO_URL"; fi
printf '%s' "$PROJECT_NAME" | clip.exe
pause 'Paste the project name; press Enter for the tagline.'
printf '%s' "$PROJECT_TAGLINE" | clip.exe
pause 'Paste the tagline; press Enter for the description.'
printf '%s' "$DESCRIPTION" | clip.exe
pause 'Paste the description body; press Enter for Built-with.'
printf '%s' "$BUILT_WITH" | clip.exe
pause 'Paste Built-with; press Enter for the repository link.'
printf '%s' "$REPOSITORY_URL" | clip.exe
pause 'Paste the repository link; press Enter for the video URL.'
printf '%s' "$VIDEO_URL" | clip.exe
pause 'Paste the video URL; press Enter for the final checklist.'
step "Upload SOURCE_ZIP: $SOURCE_ZIP"
step 'Every team member must accept the terms.'
step 'Review and submit before Sunday 8 November, 10:00 EET.'
pause 'Press Enter after submitting (the wizard does not submit for you).'

stage "Optional overnight cleanup"
if confirm 'Run optional cleanup (power settings, scheduled tasks and known helper processes)?'; then
  say "In ADMIN PowerShell: Remove-MpPreference -ExclusionPath 'C:\Users\kivas\AI'"
  pause 'Press Enter after removing the Defender exclusion (or if it was never added).'
  say 'Restore both saved schemes: power/sleep buttons and lid = Sleep (1), display idle = 1800 seconds.'
  if confirm 'Apply these power settings to both saved schemes and reactivate the current scheme?'; then
    powershell.exe -NoProfile -Command '
      $ErrorActionPreference = "Stop"
      foreach ($scheme in @("27fa6203-3987-4dcc-918d-748559d549ec", "64a64f24-65b9-4b56-befd-5ec1eaced9b3")) {
        powercfg /setacvalueindex $scheme SUB_BUTTONS PBUTTONACTION 1
        if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
        powercfg /setacvalueindex $scheme SUB_BUTTONS SBUTTONACTION 1
        if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
        powercfg /setacvalueindex $scheme SUB_VIDEO VIDEOIDLE 1800
        if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
        powercfg /setacvalueindex $scheme SUB_BUTTONS LIDACTION 1
        if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
      }
      powercfg /setactive SCHEME_CURRENT
      exit $LASTEXITCODE
    '
  fi
  if confirm 'Uninstall the overnight watchdog and utilization scheduled tasks?'; then
    powershell.exe -NoProfile -File scripts/overnight/uninstall-watchdog.ps1
    powershell.exe -NoProfile -File scripts/overnight/uninstall-utilization.ps1
  fi
  if confirm 'Stop only helper PIDs whose live command line matches the expected helper script?'; then
    powershell.exe -NoProfile -Command '
      $ErrorActionPreference = "Stop"
      $helpers = @{
        "keep-awake.pid" = "keep-awake.ps1"
        "deprioritize.pid" = "deprioritize-tests.ps1"
        "go-probe.pid" = "gpt-quota-probe.ps1"
        "gpt-probe.pid" = "gpt-quota-probe.ps1"
      }
      foreach ($name in ($helpers.Keys | Sort-Object)) {
        $file = Join-Path ".scratch/local-overnight" $name
        if (-not (Test-Path -LiteralPath $file)) { continue }
        $text = (Get-Content -LiteralPath $file -Raw).Trim()
        $helperId = 0
        if (-not [int]::TryParse($text, [ref]$helperId) -or $helperId -le 0) { throw "Invalid helper PID file: $name" }
        $process = Get-CimInstance Win32_Process -Filter "ProcessId=$helperId"
        if (-not $process) { Write-Output "Helper already stopped: $name"; continue }
        $expectedScript = [IO.Path]::GetFullPath((Join-Path "scripts/overnight" $helpers[$name]))
        $command = ([string]$process.CommandLine).Replace("/", "\")
        if (-not $command -or $command.IndexOf($expectedScript, [StringComparison]::OrdinalIgnoreCase) -lt 0) {
          throw "PID identity mismatch; refusing to stop process from $name"
        }
        if ($process.CreationDate.ToUniversalTime() -gt (Get-Item -LiteralPath $file).LastWriteTimeUtc) {
          throw "PID file predates the live process; refusing reused PID from $name"
        }
        Stop-Process -Id $helperId -ErrorAction Stop
        Write-Output "Stopped helper: $name"
      }
    '
  fi
else
  say 'Cleanup skipped; overnight settings and helpers are unchanged.'
fi

finish
}

run_wizard "$@"; exit
